MTLPixelFormat pixel(FfxmSurfaceFormat f){switch(f){
 case FFXM_SURFACE_FORMAT_R32G32B32A32_TYPELESS:case FFXM_SURFACE_FORMAT_R32G32B32A32_FLOAT:return MTLPixelFormatRGBA32Float;
