 case FFXM_SURFACE_FORMAT_R32G32_FLOAT:return MTLPixelFormatRG32Float;
 case FFXM_SURFACE_FORMAT_R32_UINT:return MTLPixelFormatR32Uint;
 case FFXM_SURFACE_FORMAT_R8G8B8A8_TYPELESS:case FFXM_SURFACE_FORMAT_R8G8B8A8_UNORM:return MTLPixelFormatRGBA8Unorm;
 case FFXM_SURFACE_FORMAT_R11G11B10_FLOAT:return MTLPixelFormatRG11B10Float;
 case FFXM_SURFACE_FORMAT_R16G16_FLOAT:return MTLPixelFormatRG16Float;
 case FFXM_SURFACE_FORMAT_R16G16_UINT:return MTLPixelFormatRG16Uint;
 case FFXM_SURFACE_FORMAT_R16_FLOAT:return MTLPixelFormatR16Float;
 case FFXM_SURFACE_FORMAT_R16_UINT:return MTLPixelFormatR16Uint;
 case FFXM_SURFACE_FORMAT_R16_UNORM:return MTLPixelFormatR16Unorm;
 case FFXM_SURFACE_FORMAT_R16_SNORM:return MTLPixelFormatR16Snorm;
 case FFXM_SURFACE_FORMAT_R8_UNORM:return MTLPixelFormatR8Unorm;
 case FFXM_SURFACE_FORMAT_R8_SNORM:return MTLPixelFormatR8Snorm;
 case FFXM_SURFACE_FORMAT_R8_UINT:return MTLPixelFormatR8Uint;
 case FFXM_SURFACE_FORMAT_R8G8_UNORM:return MTLPixelFormatRG8Unorm;
