}}
FfxmSurfaceFormat surface(MTLPixelFormat f){for(unsigned i=1;i<=FFXM_SURFACE_FORMAT_R32_FLOAT;++i)if(pixel((FfxmSurfaceFormat)i)==f)return (FfxmSurfaceFormat)i;
